fn solve(s: Vec<char>) -> Vec<char> {
    let mut buffer: Vec<char> = Vec::new();
    for c in s {
        match c {
            '0' | '1' => buffer.push(c),
            'B' => {
                buffer.pop();
            }
            _ => {} // Given the problem statement, no other characters will appear.
        }
    }
    buffer
}

